pub fn squash(v: &mut Vec<String>) {
    // Pass 1: remove consecutive duplicate strings (compared on original,
    // untrimmed values), keeping the first of each run.
    let mut write = 0usize;
    for read in 1..v.len() {
        if v[read] != v[write] {
            write += 1;
            v[write] = v[read].clone();
        }
    }
    if !v.is_empty() {
        v.truncate(write + 1);
    }

    // Pass 2: trim ASCII whitespace from both ends of every surviving string.
    for s in v.iter_mut() {
        *s = s.trim_ascii().to_string();
    }
}
