use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;

pub fn parallel_map<T, R, F>(items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let len = items.len();

    // Items are moved into a Vec<Option<T>>; each worker `take`s its item by
    // index, so every element is consumed exactly once.
    let pending: Arc<Mutex<Vec<Option<T>>>> =
        Arc::new(Mutex::new(items.into_iter().map(Some).collect()));

    // Preallocated results, indexed by the ORIGINAL input position so the
    // output order is preserved regardless of completion order.
    let results: Arc<Mutex<Vec<Option<R>>>> = Arc::new(Mutex::new(vec![None; len]));

    // Shared work counter: workers pull the next free index until exhausted.
    let next: Arc<AtomicUsize> = Arc::new(AtomicUsize::new(0));

    let f: Arc<F> = Arc::new(f);

    let worker_count = workers.max(1);
    let mut handles = Vec::with_capacity(worker_count);

    for _ in 0..worker_count {
        let pending = Arc::clone(&pending);
        let results = Arc::clone(&results);
        let next = Arc::clone(&next);
        let f = Arc::clone(&f);

        handles.push(thread::spawn(move || {
            loop {
                let idx = next.fetch_add(1, Ordering::Relaxed);
                if idx >= len {
                    break;
                }
                // Lock only long enough to claim the item; f runs unlocked.
                let item = pending.lock().unwrap().get_mut(idx).unwrap().take().unwrap();
                let r = f(item);
                results.lock().unwrap()[idx] = Some(r);
            }
        }));
    }

    for h in handles {
        h.join().unwrap();
    }

    // Every index in [0, len) is claimed exactly once, so all slots are filled.
    results
        .into_inner()
        .unwrap()
        .into_iter()
        .map(Option::unwrap)
        .collect()
}
```

The key idea: hold the unique `&mut [T]` borrow for the iterator's whole lifetime (via `PhantomData<&'a mut T>`), advance a raw pointer by 2 per step, and only ever dereference while ≥ 2 elements remain — so the two references are always in-bounds, aligned, disjoint (slice elements never overlap), and each element is emitted at most once.

```rust
use std::marker::PhantomData;

/// Iterator over non-overlapping consecutive `(&'a mut T, &'a mut T)` pairs.
///
/// For a slice of length `n` this yields exactly `n / 2` pairs, dropping an
/// odd trailing element. Each element is handed out at most once.
pub struct PairsMut<'a, T> {
    /// Points at the first element of the next pair; valid for the remaining
    /// `len` elements (an odd tail may remain, never dereferenced).
    ptr: *mut T,
    /// Number of elements remaining at `ptr`.
    len: usize,
    /// Records that the iterator holds the unique `&'a mut [T]` borrow over
    /// the whole range, keeping the lifetime and variance correct.
    _marker: PhantomData<&'a mut T>,
}

pub fn pairs_mut<'a, T>(s: &mut [T]) -> PairsMut<'a, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        len: s.len(),
        _marker: PhantomData,
    }
}

impl<'a, T> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.len < 2 {
            return None;
        }
        unsafe {
            // SAFETY:
            // * `ptr` is derived from the `&'a mut [T]` that this iterator
            //   holds, so the allocation is alive and exclusively borrowed
            //   for the entire lifetime 'a (enforced by _marker).
            // * We only reach this point with `len >= 2`, so both `ptr` and
            //   `ptr.add(1)` are in-bounds, properly aligned (element
            //   alignment of the slice), and refer to initialized elements.
            // * Adjacent elements of a slice never overlap, so the two
            //   `&mut T` references are disjoint — no aliasing.
            // * We advance `ptr` by 2 immediately, so every element is
            //   emitted at most once; the odd tail is never touched.
            let first = &mut *self.ptr;
            let second = &mut *self.ptr.add(1);
            self.ptr = self.ptr.add(2);
            self.len -= 2;
            Some((first, second))
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let pairs = self.len / 2;
        (pairs, Some(pairs))
    }
}
